console.log("This is script level Post-Req Script", pm.info.requestName)
// Check the response status code
pm.test("Response code is 200", function () {
    pm.expect(pm.response.code).to.eql(200);
});

// Check response performance and payload size
pm.test("Response time is under 2000 ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});

pm.test("Response body size is under 100 KB", function () {
    pm.expect(pm.response.size().body).to.be.below(100 * 1024);
});

const posts = pm.response.json();

// Check each element in the posts response
pm.test("Response is a non-empty array of valid posts", function () {
    pm.expect(posts).to.be.an("array").that.is.not.empty;

    posts.forEach(function (post) {
        pm.expect(post).to.be.an("object").and.not.to.be.null;
        pm.expect(post).to.have.all.keys("userId", "id", "title", "body");
        pm.expect(post.userId).to.be.a("number");
        pm.expect(post.id).to.be.a("number");
        pm.expect(post.title).to.be.a("string");
        pm.expect(post.body).to.be.a("string");
    });
});

